class Solution {
public:
    int maxLength(vector<int>& ribbons, int k) {
        int lo = 1, hi = *max_element(ribbons.begin(), ribbons.end());
        int answer = 0;
        while (lo <= hi) {
            int mid = lo + (hi - lo) / 2;
            long long pieces = 0;
            for (int length : ribbons) {
                pieces += length / mid;
            }
            if (pieces >= k) {
                answer = mid;
                lo = mid + 1;
            } else {
                hi = mid - 1;
            }
        }
        return answer;
    }
};
